const upsertRecord = `-- name: UpsertRecord :one
INSERT INTO record (project_id, collection, key, data) VALUES (?, ?, ?, ?)
ON CONFLICT (project_id, collection, key)
DO UPDATE SET data = excluded.data, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
RETURNING id, project_id, collection, "key", data, created_at, updated_at
`

type UpsertRecordParams struct {
	ProjectID  int64
	Collection string
	Key        string
	Data       string
}

func (q *Queries) UpsertRecord(ctx context.Context, arg UpsertRecordParams) (Record, error) {
	row := q.db.QueryRowContext(ctx, upsertRecord,
		arg.ProjectID,
		arg.Collection,
		arg.Key,
		arg.Data,
	)
	var i Record
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Collection,
		&i.Key,
		&i.Data,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertTrigger = `-- name: UpsertTrigger :exec
INSERT INTO trigger_state (project_id, command, cron, next_run_at) VALUES (?, ?, ?, ?)
ON CONFLICT (project_id, command, cron) DO NOTHING
`

type UpsertTriggerParams struct {
	ProjectID int64
	Command   string
	Cron      string
	NextRunAt string
}

func (q *Queries) UpsertTrigger(ctx context.Context, arg UpsertTriggerParams) error {
	_, err := q.db.ExecContext(ctx, upsertTrigger,
		arg.ProjectID,
		arg.Command,
		arg.Cron,
		arg.NextRunAt,
	)
	return err
}
